type SecurityTradesRow struct {
	TransactionID    uuid.UUID
	AccountID        uuid.UUID
	Date             time.Time
	Side             string
	Quantity         int64
	UnitPrice        pgtype.Numeric
	Gross            int64
	Fees             int64
	Taxes            int64
	Cost             *int64
	DayTradeQuantity int64
	DayTradeCost     int64
	ExchangeRate     pgtype.Numeric
}

func (q *Queries) SecurityTrades(ctx context.Context, arg SecurityTradesParams) ([]SecurityTradesRow, error) {
	rows, err := q.db.Query(ctx, securityTrades, arg.BooksID, arg.AccountIds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []SecurityTradesRow
	for rows.Next() {
		var i SecurityTradesRow
		if err := rows.Scan(
			&i.TransactionID,
			&i.AccountID,
			&i.Date,
			&i.Side,
			&i.Quantity,
			&i.UnitPrice,
			&i.Gross,
			&i.Fees,
			&i.Taxes,
			&i.Cost,
			&i.DayTradeQuantity,
			&i.DayTradeCost,
			&i.ExchangeRate,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
